hn = (@C - @C.min()) / (@C.max() - @C.min())
@hn = hn
# forest: on grassland, below the tree line (0.62), in patches
patch = smoothstep(0.38, 0.62, noise(set(@u * 9, @v * 9, 1.7)))
f = (1 - smoothstep(0.55, 0.68, hn)) * patch
@Grass = @splat_grass * (1 - f)
@ForestFloor = @splat_grass * f
@Sediment = @splat_sediment
@Rock = @splat_rock
@Snow = @splat_snow
@Water = @splat_water
# scatter densities
@d_tree = @ForestFloor
@d_bush = @Grass * smoothstep(0.4, 0.7, noise(set(@u * 23, @v * 23, 5.3)))
@d_rock = smoothstep(0.15, 0.5, @Rock) * (1 - 0.7 * @Rock) + 0.35 * @Sediment
# terrain normal to world space (image x → world +X, image y (north) → world −Z, z → +Y)
@tn = normalize(set(@N.x, @N.z, -@N.y))
# colour for preview / minimap: lush and dry grass in patches, darker rock lower down, bluish water. Picked as
# display (sRGB) values and made linear at the end (the minimap is written with an sRGB encode, the mesh preview
# treats Cd as linear) -- without it everything came out pale lime
dry = smoothstep(0.35, 0.7, noise(set(@u * 6, @v * 6, 4.4)) + 0.25 * hn)
grass = lerp(set(0.27, 0.34, 0.16), set(0.43, 0.42, 0.26), dry)
rock = lerp(set(0.36, 0.34, 0.31), set(0.52, 0.50, 0.47), smoothstep(0.3, 0.8, hn))
c = (grass * @Grass + set(0.19, 0.24, 0.12) * @ForestFloor + set(0.50, 0.45, 0.36) * @Sediment + rock * @Rock + set(0.90, 0.91, 0.94) * @Snow + set(0.13, 0.21, 0.25) * @Water)
@albedo = (c * (0.92 + 0.16 * noise(set(@u * 60, @v * 60, 2.2)))) ** 2.2

r = rand(@ptnum + 0.5)
pine = np.array(["Tree_Pine_A", "Tree_Pine_B", "Tree_Pine_C"])
broad = np.array(["Tree_Broadleaf_A", "Tree_Broadleaf_B"])
# pines up high, broadleaf down low, a mixed band in between (by altitude + random)
high = @hn.x + 0.08 * (rand(@ptnum + 7.1) - 0.5) > 0.42
s@name = where(high, pine[(r * 3).astype(int)], broad[(r * 2).astype(int)])
a = rand(@ptnum + 1.3) * 2 * PI
@N = set(sin(a), 0 * a, cos(a))
@up = set(0, 1, 0)
@pscale = 0.75 + 0.55 * rand(@ptnum + 2.9)

names = np.array(["Bush_A", "Bush_B"])
s@name = names[(rand(@ptnum + 0.3) * 2).astype(int)]
a = rand(@ptnum + 1.7) * 2 * PI
@N = set(sin(a), 0 * a, cos(a))
@up = normalize(lerp(set(0, 1, 0), @tn, 0.4))
@pscale = 0.6 + 0.8 * rand(@ptnum + 4.1)

s@name = sprintf("SM_Rock_%02d", (rand(@ptnum + 0.9) * 4).astype(int))
# follow the slope (up tilted 70% towards the terrain normal), sunk in a bit
@up = normalize(lerp(set(0, 1, 0), @tn, 0.7))
a = rand(@ptnum + 3.3) * 2 * PI
@N = normalize(cross(@up, set(sin(a), 0 * a, cos(a))))
@pscale = 0.5 + 1.6 * pow(rand(@ptnum + 5.5), 2)
@P.y -= 0.25 * @pscale
